pub(crate) fn get_syntax_for(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
    let path = path.as_ref();
    let candidate = Candidate::new(path);
    let candidate_filename = path.file_name().map(Candidate::new);
    for (ref glob, ref syntax) in self.mappings.iter().rev() {
        if glob.is_match_candidate(&candidate)
            || candidate_filename
                .as_ref()
                .map_or(false, |filename| glob.is_match_candidate(filename))
        {
            return Some(*syntax);
        }
    }

    // If no mapping matched, try again after stripping an ignored suffix
    // from the file name (e.g. `foo.rs.bak` -> `foo.rs`).
    let file_name = path.file_name()?.to_str()?;
    let stripped_file_name = self.ignored_suffixes.strip_suffix(file_name)?;
    if stripped_file_name == file_name {
        return None;
    }
    self.get_syntax_for(path.with_file_name(OsStr::new(stripped_file_name)))
}

